CREATE TABLE silver.session_minute_sate_adv (`video_session_id` FixedString(64), `user_id` FixedString(64), `bucket_start` DateTime, `has_active_event` SimpleAggregateFunction(max, UInt8), `has_stop_event` SimpleAggregateFunction(max, UInt8), `first_active_at` SimpleAggregateFunction(min, DateTime64(3, 'UTC')), `last_active_at` SimpleAggregateFunction(max, DateTime64(3, 'UTC')), `first_stop_at` SimpleAggregateFunction(min, DateTime64(3, 'UTC')), `last_stop_at` SimpleAggregateFunction(max, DateTime64(3, 'UTC'))) ENGINE = SharedAggregatingMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(bucket_start) ORDER BY (video_session_id, user_id, bucket_start) SETTINGS index_granularity = 8192